<?php
// ============================================================
// Database Management API
// backend/api/database_api.php
// Handles backup, restore, schema, replication, and logs
// ============================================================  if (session_status() === PHP_SESSION_NONE) session_start();
require_once __DIR__ . '/../lib.php';
require_once __DIR__ . '/../../public/db_connect.php';
require_login();  header('Content-Type: application/json');  $me = current_user();
$role = role_key($me['role'] ?? '');  // Only SuperAdmin access
if ($role !== 'superadmin') {  echo json_encode(['ok' => false, 'error' => 'Access denied. SuperAdmin role required.']);  exit;
}  $action = $_GET['action'] ?? $_POST['action'] ?? '';  // CSRF validation for POST requests
if ($_SERVER['REQUEST_METHOD'] === 'POST') {  $csrf = $_POST['csrf_token'] ?? '';  if (empty($csrf) || $csrf !== ($_SESSION['csrf_token'] ?? '')) {  echo json_encode(['ok' => false, 'error' => 'Invalid CSRF token']);  exit;  }
}  // Helper to extract specific tables from a SQL dump
function extract_tables_from_sql($filepath, $tables) {  $fp = fopen($filepath, 'r');  if (!$fp) return false;  $temp_filepath = tempnam(sys_get_temp_dir(), 'restore_');  $out_fp = fopen($temp_filepath, 'w');  if (!$out_fp) {  fclose($fp);  return false;  }  $active_table = null;  $in_table_section = false;  $table_lookup = array_flip($tables);  while (($line = fgets($fp)) !== false) {  if (preg_match('/^-- (Table structure for table|Dumping data for table|Temporary table structure for view|Final view structure for view) `([^`]+)`/', $line, $matches)) {  $active_table = $matches[2];  $in_table_section = isset($table_lookup[$active_table]);  }  $is_generic_setup = false;  if (strpos($line, '/*!') === 0 || strpos($line, 'SET ') === 0 || (strpos($line, '--') === 0 && !preg_match('/^-- (Table structure for table|Dumping data for table|Temporary table structure for view|Final view structure for view)/', $line))) {  $is_generic_setup = true;  }  if ($in_table_section || $is_generic_setup) {  fwrite($out_fp, $line);  }  }  fclose($fp);  fclose($out_fp);  return $temp_filepath;
}  try {  switch ($action) {  // ══════════════════════════════════════════════════════════════  // 1. BACKUP OPERATIONS  // ══════════════════════════════════════════════════════════════  case 'backup':  $backup_dir = __DIR__ . '/../../backups/';  if (!is_dir($backup_dir)) {  mkdir($backup_dir, 0755, true);  }  $filename = 'backup_' . date('Y_m_d_His') . '.sql';  $filepath = $backup_dir . $filename;  // Get database name from PDO  $db_name = $pdo->query('SELECT DATABASE()')->fetchColumn();  // Execute mysqldump  $command = sprintf(  'C:\\xampp\\mysql\\bin\\mysqldump.exe --host=127.0.0.1 -u root %s > %s 2>&1',  escapeshellarg($db_name),  escapeshellarg($filepath)  );  exec($command, $output, $return_code);  if ($return_code === 0 && file_exists($filepath)) {  // Log backup inside system_backups  $stmt = $pdo->prepare("  INSERT INTO system_backups (backup_name, backup_type, file_path, file_size, status, created_by, created_at, completed_at, backup_path)  VALUES (?, 'database', ?, ?, 'completed', ?, NOW(), NOW(), ?)  ");  $stmt->execute([$filename, 'backups/' . $filename, filesize($filepath), $me['id'], $filepath]);  $backup_id = $pdo->lastInsertId();  // Log action inside backup_logs  $stmt_log = $pdo->prepare("  INSERT INTO backup_logs (backup_id, action, status, details)  VALUES (?, 'create', 'success', 'Database backup created successfully')  ");  $stmt_log->execute([$backup_id]);  // Log in user activity  $stmt_act = $pdo->prepare("  INSERT INTO user_activity_logs (user_id, action, details, ip_address)  VALUES (?, 'Backup Database', ?, ?)  ");  $stmt_act->execute([$me['id'], "Created backup: $filename", $_SERVER['REMOTE_ADDR'] ?? '127.0.0.1']);  echo json_encode([  'ok' => true,  'message' => 'Backup created successfully',  'filename' => $filename,  'size' => round(filesize($filepath) / 1024 / 1024, 2) . ' MB'  ]);  } else {  echo json_encode(['ok' => false, 'error' => 'Backup failed: ' . implode("\n", $output)]);  }  break;  case 'save_backup_config':  $frequency = $_POST['frequency'] ?? 'manual';  $storage = $_POST['storage'] ?? 'local';  $retention = (int)($_POST['retention'] ?? 30);  // Validate inputs  if (!in_array($frequency, ['manual', 'daily', 'weekly', 'monthly'])) {  echo json_encode(['ok' => false, 'error' => 'Invalid frequency']);  exit;  }  if (!in_array($storage, ['local', 'cloud', 'both'])) {  echo json_encode(['ok' => false, 'error' => 'Invalid storage location']);  exit;  }  if ($retention < 1 || $retention > 365) {  echo json_encode(['ok' => false, 'error' => 'Retention must be 1-365 days']);  exit;  }  // Save to config table  $configs = [  ['backup_frequency', $frequency],  ['backup_storage', $storage],  ['backup_retention_days', (string)$retention]  ];  foreach ($configs as [$key, $value]) {  $stmt = $pdo->prepare("  INSERT INTO system_config (config_key, config_value, updated_by, updated_at)  VALUES (?, ?, ?, NOW())  ON DUPLICATE KEY UPDATE  config_value = VALUES(config_value),  updated_by = VALUES(updated_by),  updated_at = NOW()  ");  $stmt->execute([$key, $value, $me['id']]);  }  echo json_encode(['ok' => true, 'message' => 'Backup configuration saved successfully']);  break;  case 'get_backup_config':  $config = [];  $stmt = $pdo->query("  SELECT config_key, config_value  FROM system_config  WHERE config_key IN ('backup_frequency', 'backup_storage', 'backup_retention_days')  ");  while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {  $config[$row['config_key']] = $row['config_value'];  }  echo json_encode([  'ok' => true,  'config' => [  'frequency' => $config['backup_frequency'] ?? 'daily',  'storage' => $config['backup_storage'] ?? 'local',  'retention' => $config['backup_retention_days'] ?? '30'  ]  ]);  break;  case 'get_backups':  $stmt = $pdo->query("  SELECT  backup_name as filename,  ROUND(file_size / 1024 / 1024, 2) as size,  DATE_FORMAT(created_at, '%Y-%m-%d %H:%i:%s') as date  FROM system_backups  WHERE status = 'completed'  ORDER BY created_at DESC  LIMIT 100  ");  $backups = $stmt->fetchAll(PDO::FETCH_ASSOC);  // Format size for UI  foreach ($backups as &$b) {  $b['size'] = ($b['size'] ?? 0) . ' MB';  }  echo json_encode(['ok' => true, 'backups' => $backups]);  break;  case 'delete_backup':  $filename = basename($_POST['filename'] ?? '');  if (empty($filename)) {  echo json_encode(['ok' => false, 'error' => 'No filename provided']);  exit;  }  $backup_dir = __DIR__ . '/../../backups/';  $filepath = $backup_dir . $filename;  if (!file_exists($filepath)) {  echo json_encode(['ok' => false, 'error' => 'Backup file not found']);  exit;  }  if (unlink($filepath)) {  // Log deletion inside system_backups  $stmt = $pdo->prepare("  DELETE FROM system_backups WHERE backup_name = ?  ");  $stmt->execute([$filename]);  // Log in user activity  $stmt_act = $pdo->prepare("  INSERT INTO user_activity_logs (user_id, action, details, ip_address)  VALUES (?, 'Delete Backup', ?, ?)  ");  $stmt_act->execute([$me['id'], "Deleted backup file: $filename", $_SERVER['REMOTE_ADDR'] ?? '127.0.0.1']);  echo json_encode(['ok' => true, 'message' => 'Backup deleted successfully']);  } else {  echo json_encode(['ok' => false, 'error' => 'Failed to delete backup file']);  }  break;  // ══════════════════════════════════════════════════════════════  // 2. RESTORE OPERATIONS  // ══════════════════════════════════════════════════════════════  case 'restore':  $backup_file = $_POST['backup_file'] ?? '';  $scope = $_POST['scope'] ?? 'full';  if (empty($backup_file)) {  echo json_encode(['ok' => false, 'error' => 'No backup file specified']);  exit;  }  $backup_path = __DIR__ . '/../../backups/' . basename($backup_file);  if (!file_exists($backup_path)) {  echo json_encode(['ok' => false, 'error' => 'Backup file not found']);  exit;  }  $db_name = $pdo->query('SELECT DATABASE()')->fetchColumn();  $restore_file = $backup_path;  $temp_file = null;  if ($scope === 'partial') {  $tables_str = $_POST['tables'] ?? '';  if (empty($tables_str)) {  echo json_encode(['ok' => false, 'error' => 'No tables specified for partial restore']);  exit;  }  $tables = explode(',', $tables_str);  $stmt_t = $pdo->query("SHOW TABLES");  $db_tables = $stmt_t->fetchAll(PDO::FETCH_COLUMN);  $valid_tables = [];  foreach ($tables as $t) {  $t = trim($t);  if (in_array($t, $db_tables)) {  $valid_tables[] = $t;  }  }  if (empty($valid_tables)) {  echo json_encode(['ok' => false, 'error' => 'No valid tables specified for restore']);  exit;  }  $temp_file = extract_tables_from_sql($backup_path, $valid_tables);  if (!$temp_file) {  echo json_encode(['ok' => false, 'error' => 'Failed to process partial restore file']);  exit;  }  $restore_file = $temp_file;  }  // Execute mysql restore  $command = sprintf(  'C:\\xampp\\mysql\\bin\\mysql.exe --host=127.0.0.1 -u root %s < %s 2>&1',  escapeshellarg($db_name),  escapeshellarg($restore_file)  );  exec($command, $output, $return_code);  if ($temp_file && file_exists($temp_file)) {  unlink($temp_file);  }  if ($return_code === 0) {  // Log restore inside restore_logs  $stmt = $pdo->prepare("  INSERT INTO restore_logs (backup_name, restored_by, status, details)  VALUES (?, ?, 'success', ?)  ");  $stmt->execute([$backup_file, $me['id'], "Database restored successfully. Scope: $scope"]);  // Log in user activity  $stmt_act = $pdo->prepare("  INSERT INTO user_activity_logs (user_id, action, details, ip_address)  VALUES (?, 'Restore Database', ?, ?)  ");  $stmt_act->execute([$me['id'], "Restored database from: $backup_file (Scope: $scope)", $_SERVER['REMOTE_ADDR'] ?? '127.0.0.1']);  // Log system event  $stmt_evt = $pdo->prepare("  INSERT INTO system_events (event_type, severity, message, source)  VALUES ('DATABASE_RESTORE', 'warning', ?, 'System Restore Manager')  ");  $stmt_evt->execute(["Database restored from backup: $backup_file by user ID: " . $me['id']]);  echo json_encode(['ok' => true, 'message' => 'Database restored successfully']);  } else {  echo json_encode(['ok' => false, 'error' => 'Restore failed: ' . implode("\n", $output)]);  }  break;  // ══════════════════════════════════════════════════════════════  // 3. SCHEMA OPERATIONS  // ══════════════════════════════════════════════════════════════  case 'get_tables':  $stmt = $pdo->query("SHOW TABLES");  $tables = $stmt->fetchAll(PDO::FETCH_COLUMN);  echo json_encode(['ok' => true, 'tables' => $tables]);  break;  case 'get_table_structure':  $table = $_GET['table'] ?? '';  if (empty($table)) {  echo json_encode(['ok' => false, 'error' => 'No table specified']);  exit;  }  // Validate table exists  $stmt = $pdo->query("SHOW TABLES");  $tables = $stmt->fetchAll(PDO::FETCH_COLUMN);  if (!in_array($table, $tables)) {  echo json_encode(['ok' => false, 'error' => 'Table not found']);  exit;  }  // Get table structure  $stmt = $pdo->prepare("DESCRIBE `$table`");  $stmt->execute();  $columns = $stmt->fetchAll(PDO::FETCH_ASSOC);  echo json_encode(['ok' => true, 'columns' => $columns]);  break;  case 'optimize':  $stmt = $pdo->query("SELECT TABLE_NAME FROM information_schema.tables WHERE table_schema = DATABASE()");  $tables = $stmt->fetchAll(PDO::FETCH_COLUMN);  $optimized = 0;  foreach ($tables as $table) {  try {  $pdo->exec("OPTIMIZE TABLE `$table`");  $optimized++;  } catch (Exception $e) {  // Skip tables that can't be optimized  }  }  echo json_encode(['ok' => true, 'message' => "Optimized $optimized tables successfully"]);  break;  case 'add_column':  $table = $_POST['table'] ?? '';  $columnName = $_POST['column_name'] ?? '';  $columnType = $_POST['column_type'] ?? '';  $columnLength = $_POST['column_length'] ?? '';  $allowNull = $_POST['allow_null'] ?? '0';  if (empty($table) || empty($columnName) || empty($columnType)) {  echo json_encode(['ok' => false, 'error' => 'Missing required fields']);  exit;  }  // Build ALTER TABLE query  $typeDefinition = $columnType;  if ($columnLength && in_array($columnType, ['VARCHAR', 'CHAR'])) {  $typeDefinition .= "($columnLength)";  }  $nullClause = $allowNull === '1' ? 'NULL' : 'NOT NULL';  $sql = "ALTER TABLE `$table` ADD COLUMN `$columnName` $typeDefinition $nullClause";  try {  $pdo->exec($sql);  // Log into migration_history  $mig_name = "ADD COLUMN `$columnName` ($typeDefinition) TO `$table`";  $stmt = $pdo->prepare("  INSERT INTO migration_history (migration_name, status, executed_by)  VALUES (?, 'success', ?)  ");  $stmt->execute([$mig_name, $me['id']]);  // Update schema_versions with incremented patch version  $ver_row = $pdo->query("SELECT version FROM schema_versions ORDER BY applied_at DESC LIMIT 1")->fetch(PDO::FETCH_ASSOC);  $parts = explode('.', $ver_row['version'] ?? '1.0.0');  $parts[2] = (int)($parts[2] ?? 0) + 1;  $new_ver = implode('.', $parts);  $pdo->prepare("INSERT INTO schema_versions (version, description, applied_by) VALUES (?, ?, ?)")  ->execute([$new_ver, $mig_name, $me['id']]);  echo json_encode(['ok' => true, 'message' => 'Column added successfully', 'new_version' => $new_ver]);  } catch (Exception $e) {  // Log failure  $pdo->prepare("INSERT INTO migration_history (migration_name, status, executed_by, error_message) VALUES (?, 'failed', ?, ?)")  ->execute(["ADD COLUMN $columnName TO $table", $me['id'], $e->getMessage()]);  echo json_encode(['ok' => false, 'error' => 'Failed to add column: ' . $e->getMessage()]);  }  break;  case 'modify_column':  $table = $_POST['table'] ?? '';  $oldName = $_POST['old_name'] ?? '';  $newName = $_POST['new_name'] ?? '';  $columnType = $_POST['column_type'] ?? '';  $columnLength = $_POST['column_length'] ?? '';  $allowNull = $_POST['allow_null'] ?? '0';  if (empty($table) || empty($oldName)) {  echo json_encode(['ok' => false, 'error' => 'Missing required fields']);  exit;  }  // Get current column definition if type not specified  if (empty($columnType)) {  $stmt = $pdo->prepare("DESCRIBE `$table` `$oldName`");  $stmt->execute();  $current = $stmt->fetch(PDO::FETCH_ASSOC);  if (!$current) {  echo json_encode(['ok' => false, 'error' => 'Column not found']);  exit;  }  $typeDefinition = $current['Type'];  $nullClause = $current['Null'] === 'YES' ? 'NULL' : 'NOT NULL';  } else {  $typeDefinition = $columnType;  if ($columnLength && in_array($columnType, ['VARCHAR', 'CHAR'])) {  $typeDefinition .= "($columnLength)";  }  $nullClause = $allowNull === '1' ? 'NULL' : 'NOT NULL';  }  $sql = "ALTER TABLE `$table` CHANGE COLUMN `$oldName` `$newName` $typeDefinition $nullClause";  try {  $pdo->exec($sql);  $mig_name = "RENAME COLUMN `$oldName` -> `$newName` IN `$table`";  $pdo->prepare("INSERT INTO migration_history (migration_name, status, executed_by) VALUES (?, 'success', ?)")  ->execute([$mig_name, $me['id']]);  $ver_row = $pdo->query("SELECT version FROM schema_versions ORDER BY applied_at DESC LIMIT 1")->fetch(PDO::FETCH_ASSOC);  $parts = explode('.', $ver_row['version'] ?? '1.0.0');  $parts[2] = (int)($parts[2] ?? 0) + 1;  $new_ver = implode('.', $parts);  $pdo->prepare("INSERT INTO schema_versions (version, description, applied_by) VALUES (?, ?, ?)")  ->execute([$new_ver, $mig_name, $me['id']]);  echo json_encode(['ok' => true, 'message' => 'Column modified successfully', 'new_version' => $new_ver]);  } catch (Exception $e) {  $pdo->prepare("INSERT INTO migration_history (migration_name, status, executed_by, error_message) VALUES (?, 'failed', ?, ?)")  ->execute(["RENAME COLUMN $oldName IN $table", $me['id'], $e->getMessage()]);  echo json_encode(['ok' => false, 'error' => 'Failed to modify column: ' . $e->getMessage()]);  }  break;  case 'remove_column':  $table = $_POST['table'] ?? '';  $columnName = $_POST['column_name'] ?? '';  if (empty($table) || empty($columnName)) {  echo json_encode(['ok' => false, 'error' => 'Missing required fields']);  exit;  }  $sql = "ALTER TABLE `$table` DROP COLUMN `$columnName`";  try {  $pdo->exec($sql);  $mig_name = "DROP COLUMN `$columnName` FROM `$table`";  $pdo->prepare("INSERT INTO migration_history (migration_name, status, executed_by) VALUES (?, 'success', ?)")  ->execute([$mig_name, $me['id']]);  $ver_row = $pdo->query("SELECT version FROM schema_versions ORDER BY applied_at DESC LIMIT 1")->fetch(PDO::FETCH_ASSOC);  $parts = explode('.', $ver_row['version'] ?? '1.0.0');  $parts[2] = (int)($parts[2] ?? 0) + 1;  $new_ver = implode('.', $parts);  $pdo->prepare("INSERT INTO schema_versions (version, description, applied_by) VALUES (?, ?, ?)")  ->execute([$new_ver, $mig_name, $me['id']]);  echo json_encode(['ok' => true, 'message' => 'Column removed successfully', 'new_version' => $new_ver]);  } catch (Exception $e) {  $pdo->prepare("INSERT INTO migration_history (migration_name, status, executed_by, error_message) VALUES (?, 'failed', ?, ?)")  ->execute(["DROP COLUMN $columnName FROM $table", $me['id'], $e->getMessage()]);  echo json_encode(['ok' => false, 'error' => 'Failed to remove column: ' . $e->getMessage()]);  }  break;  // ══════════════════════════════════════════════════════════════  // 4. REPLICATION OPERATIONS  // ══════════════════════════════════════════════════════════════  case 'get_schema_history':  // Fetch current version from schema_versions  $cur_ver = $pdo->query("  SELECT version, description, DATE_FORMAT(applied_at, '%Y-%m-%d %H:%i:%s') as applied_at  FROM schema_versions ORDER BY applied_at DESC LIMIT 1  ")->fetch(PDO::FETCH_ASSOC);  // Fetch migration history from migration_history  $stmt = $pdo->query("  SELECT  mh.migration_name,  mh.status,  CONCAT(u.first_name, ' ', u.last_name) as executed_by,  DATE_FORMAT(mh.executed_at, '%Y-%m-%d %H:%i:%s') as executed_at,  mh.error_message  FROM migration_history mh  LEFT JOIN users u ON u.id = mh.executed_by  ORDER BY mh.executed_at DESC  LIMIT 100  ");  $migrations = $stmt->fetchAll(PDO::FETCH_ASSOC);  echo json_encode([  'ok' => true,  'current_version' => $cur_ver['version'] ?? '1.0.0',  'version_date' => $cur_ver['applied_at'] ?? null,  'migrations' => $migrations  ]);  break;  case 'get_restore_history':  $stmt = $pdo->query("  SELECT  rl.backup_name,  rl.status,  rl.details,  CONCAT(u.first_name, ' ', u.last_name) as restored_by,  DATE_FORMAT(rl.restored_at, '%Y-%m-%d %H:%i:%s') as restored_at  FROM restore_logs rl  LEFT JOIN users u ON u.id = rl.restored_by  ORDER BY rl.restored_at DESC  LIMIT 100  ");  $restores = $stmt->fetchAll(PDO::FETCH_ASSOC);  echo json_encode(['ok' => true, 'restores' => $restores]);  break;  // ══════════════════════════════════════════════════════════════  // 5. REPLICATION OPERATIONS  // ══════════════════════════════════════════════════════════════  case 'enable_replication':  $rep_station = (int)($_POST['station_id'] ?? 0);  // Update replication_status table per station  if ($rep_station > 0) {  $pdo->prepare("  INSERT INTO replication_status (station_id, status, last_sync_at)  VALUES (?, 'enabled', NOW())  ON DUPLICATE KEY UPDATE status = 'enabled', last_sync_at = NOW()  ")->execute([$rep_station]);  // Log sync event  $pdo->prepare("INSERT INTO sync_logs (station_id, status, records_synced) VALUES (?, 'success', 0)")  ->execute([$rep_station]);  }  // Also update global config  $pdo->prepare("  INSERT INTO system_config (config_key, config_value, updated_by, updated_at)  VALUES ('replication_enabled', '1', ?, NOW())  ON DUPLICATE KEY UPDATE config_value='1', updated_by=VALUES(updated_by), updated_at=NOW()  ")->execute([$me['id']]);  echo json_encode(['ok' => true, 'message' => 'Replication enabled']);  break;  case 'disable_replication':  $rep_station = (int)($_POST['station_id'] ?? 0);  if ($rep_station > 0) {  $pdo->prepare("  INSERT INTO replication_status (station_id, status)  VALUES (?, 'disabled')  ON DUPLICATE KEY UPDATE status = 'disabled'  ")->execute([$rep_station]);  }  $pdo->prepare("  INSERT INTO system_config (config_key, config_value, updated_by, updated_at)  VALUES ('replication_enabled', '0', ?, NOW())  ON DUPLICATE KEY UPDATE config_value='0', updated_by=VALUES(updated_by), updated_at=NOW()  ")->execute([$me['id']]);  echo json_encode(['ok' => true, 'message' => 'Replication disabled']);  break;  case 'save_replication_config':  $rep_station = (int)($_POST['station'] ?? 0);  $frequency = $_POST['frequency'] ?? 'daily';  $resolution = $_POST['resolution'] ?? 'server_wins';  // Upsert replication_status row for this station  if ($rep_station > 0) {  $pdo->prepare("  INSERT INTO replication_status (station_id, status, sync_frequency, conflict_resolution)  VALUES (?, 'enabled', ?, ?)  ON DUPLICATE KEY UPDATE  sync_frequency = VALUES(sync_frequency),  conflict_resolution = VALUES(conflict_resolution)  ")->execute([$rep_station, $frequency, $resolution]);  }  // Also persist global config keys  foreach ([  ['replication_station', (string)$rep_station],  ['replication_frequency', $frequency],  ['conflict_resolution', $resolution]  ] as [$key, $val]) {  $pdo->prepare("  INSERT INTO system_config (config_key, config_value, updated_by, updated_at)  VALUES (?, ?, ?, NOW())  ON DUPLICATE KEY UPDATE config_value=VALUES(config_value), updated_by=VALUES(updated_by), updated_at=NOW()  ")->execute([$key, $val, $me['id']]);  }  echo json_encode(['ok' => true, 'message' => 'Replication settings saved']);  break;  case 'get_sync_status':  // Fetch per-station replication statuses  $stmt = $pdo->query("  SELECT  rs.station_id,  s.name as station_name,  rs.status,  rs.sync_frequency,  rs.conflict_resolution,  DATE_FORMAT(rs.last_sync_at, '%Y-%m-%d %H:%i:%s') as last_sync_at  FROM replication_status rs  LEFT JOIN stations s ON s.id = rs.station_id  ORDER BY s.name ASC  ");  $station_statuses = $stmt->fetchAll(PDO::FETCH_ASSOC);  // Fetch recent sync logs  $stmt2 = $pdo->query("  SELECT  sl.station_id,  s.name as station_name,  sl.status,  sl.records_synced,  sl.error_message,  DATE_FORMAT(sl.synced_at, '%Y-%m-%d %H:%i:%s') as synced_at  FROM sync_logs sl  LEFT JOIN stations s ON s.id = sl.station_id  ORDER BY sl.synced_at DESC  LIMIT 50  ");  $sync_logs_data = $stmt2->fetchAll(PDO::FETCH_ASSOC);  // Also fetch global config for backward compat  $config = [];  $cfg_stmt = $pdo->query("  SELECT config_key, config_value FROM system_config  WHERE config_key IN ('replication_enabled','replication_station','replication_frequency','conflict_resolution','replication_last_sync')  ");  while ($row = $cfg_stmt->fetch(PDO::FETCH_ASSOC)) {  $config[$row['config_key']] = $row['config_value'];  }  echo json_encode([  'ok' => true,  'status' => [  'enabled' => $config['replication_enabled'] ?? '0',  'station' => $config['replication_station'] ?? '',  'frequency' => $config['replication_frequency'] ?? 'daily',  'resolution' => $config['conflict_resolution'] ?? 'server_wins',  'frequency_label' => ucfirst($config['replication_frequency'] ?? 'daily'),  'resolution_label' => ucfirst(str_replace('_', ' ', $config['conflict_resolution'] ?? 'server_wins')),  'last_sync' => $config['replication_last_sync'] ?? 'Never'  ],  'station_statuses' => $station_statuses,  'sync_logs' => $sync_logs_data  ]);  break;  // ══════════════════════════════════════════════════════════════  // 5. SECURITY LOGS  // ══════════════════════════════════════════════════════════════  case 'get_security_logs':  $where = [];  $params = [];  $date_from = $_GET['date_from'] ?? '';  $date_to = $_GET['date_to'] ?? '';  $user_id = $_GET['user_id'] ?? '';  $station = $_GET['station'] ?? '';  $action_type = $_GET['action_type'] ?? '';  if (!empty($date_from)) {  $where[] = "DATE(raw_time) >= ?";  $params[] = $date_from;  }  if (!empty($date_to)) {  $where[] = "DATE(raw_time) <= ?";  $params[] = $date_to;  }  if (!empty($user_id)) {  $where[] = "(user_id = ? OR user LIKE ?)";  $params[] = $user_id;  $params[] = "%$user_id%";  }  if (!empty($station)) {  $where[] = "station_id = ?";  $params[] = $station;  }  if (!empty($action_type)) {  $where[] = "action = ?";  $params[] = $action_type;  }  $where_clause = count($where) > 0 ? "WHERE " . implode(' AND ', $where) : "";  $query = "  SELECT * FROM (  (  SELECT  al.created_at as raw_time,  DATE_FORMAT(al.created_at, '%Y-%m-%d %H:%i:%s') as timestamp,  CONCAT(u.first_name, ' ', u.last_name) as user,  al.action_type as action,  al.ip_address as ip,  al.status as status,  al.user_id,  u.station_id,  al.action_details as details  FROM audit_logs al  LEFT JOIN users u ON u.id = al.user_id  )  UNION ALL  (  SELECT  ual.created_at as raw_time,  DATE_FORMAT(ual.created_at, '%Y-%m-%d %H:%i:%s') as timestamp,  CONCAT(u.first_name, ' ', u.last_name) as user,  ual.action as action,  ual.ip_address as ip,  'success' as status,  ual.user_id,  u.station_id,  ual.details as details  FROM user_activity_logs ual  LEFT JOIN users u ON u.id = ual.user_id  )  UNION ALL  (  SELECT  se.created_at as raw_time,  DATE_FORMAT(se.created_at, '%Y-%m-%d %H:%i:%s') as timestamp,  se.source as user,  se.event_type as action,  'system' as ip,  se.severity as status,  NULL as user_id,  NULL as station_id,  se.message as details  FROM system_events se  )  ) AS unified_logs  $where_clause  ORDER BY raw_time DESC  LIMIT 100  ";  $stmt = $pdo->prepare($query);  $stmt->execute($params);  $logs = $stmt->fetchAll(PDO::FETCH_ASSOC);  echo json_encode(['ok' => true, 'logs' => $logs]);  break;  case 'export_logs':  // Export logs to Excel  header('Content-Type: application/vnd.ms-excel');  header('Content-Disposition: attachment; filename="security_logs_' . date('Y-m-d') . '.xls"');  $where = [];  $params = [];  $date_from = $_GET['date_from'] ?? $_POST['date_from'] ?? '';  $date_to = $_GET['date_to'] ?? $_POST['date_to'] ?? '';  $user_id = $_GET['user_id'] ?? $_POST['user_id'] ?? '';  $station = $_GET['station'] ?? $_POST['station'] ?? '';  $action_type = $_GET['action_type'] ?? $_POST['action_type'] ?? '';  if (!empty($date_from)) {  $where[] = "DATE(raw_time) >= ?";  $params[] = $date_from;  }  if (!empty($date_to)) {  $where[] = "DATE(raw_time) <= ?";  $params[] = $date_to;  }  if (!empty($user_id)) {  $where[] = "(user_id = ? OR user LIKE ?)";  $params[] = $user_id;  $params[] = "%$user_id%";  }  if (!empty($station)) {  $where[] = "station_id = ?";  $params[] = $station;  }  if (!empty($action_type)) {  $where[] = "action = ?";  $params[] = $action_type;  }  $where_clause = count($where) > 0 ? "WHERE " . implode(' AND ', $where) : "";  $query = "  SELECT * FROM (  (  SELECT  al.created_at as raw_time,  DATE_FORMAT(al.created_at, '%Y-%m-%d %H:%i:%s') as timestamp,  CONCAT(u.first_name, ' ', u.last_name) as user,  al.action_type as action,  al.ip_address as ip,  al.status as status,  al.user_id,  u.station_id,  al.action_details as details  FROM audit_logs al  LEFT JOIN users u ON u.id = al.user_id  )  UNION ALL  (  SELECT  ual.created_at as raw_time,  DATE_FORMAT(ual.created_at, '%Y-%m-%d %H:%i:%s') as timestamp,  CONCAT(u.first_name, ' ', u.last_name) as user,  ual.action as action,  ual.ip_address as ip,  'success' as status,  ual.user_id,  u.station_id,  ual.details as details  FROM user_activity_logs ual  LEFT JOIN users u ON u.id = ual.user_id  )  UNION ALL  (  SELECT  se.created_at as raw_time,  DATE_FORMAT(se.created_at, '%Y-%m-%d %H:%i:%s') as timestamp,  se.source as user,  se.event_type as action,  'system' as ip,  se.severity as status,  NULL as user_id,  NULL as station_id,  se.message as details  FROM system_events se  )  ) AS unified_logs  $where_clause  ORDER BY raw_time DESC  LIMIT 1000  ";  $stmt = $pdo->prepare($query);  $stmt->execute($params);  // Output as Excel  echo "<table border='1'>";  echo "<tr><th>Timestamp</th><th>User</th><th>Action</th><th>IP Address</th><th>Details</th><th>Status</th></tr>";  while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {  echo "<tr>";  echo "<td>" . htmlspecialchars($row['timestamp']) . "</td>";  echo "<td>" . htmlspecialchars($row['user']) . "</td>";  echo "<td>" . htmlspecialchars($row['action']) . "</td>";  echo "<td>" . htmlspecialchars($row['ip']) . "</td>";  echo "<td>" . htmlspecialchars($row['details'] ?? '') . "</td>";  echo "<td>" . ucfirst($row['status']) . "</td>";  echo "</tr>";  }  echo "</table>";  exit;  case 'get_alert_settings':  $settings = [];  $stmt = $pdo->query("  SELECT config_key, config_value  FROM system_config  WHERE config_key LIKE 'alert_%'  ");  while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {  $key = str_replace('alert_', '', $row['config_key']);  $settings[$key] = $row['config_value'];  }  echo json_encode(['ok' => true, 'settings' => $settings]);  break;  case 'save_alert_settings':  $settings = [  ['alert_failed_logins', $_POST['failed_logins'] ?? '0'],  ['alert_unauthorized_access', $_POST['unauthorized_access'] ?? '0'],  ['alert_schema_changes', $_POST['schema_changes'] ?? '0'],  ['alert_data_deletion', $_POST['data_deletion'] ?? '0'],  ['alert_backup_failure', $_POST['backup_failure'] ?? '0'],  ['alert_emails', $_POST['emails'] ?? ''],  ['alert_frequency', $_POST['frequency'] ?? 'immediate']  ];  foreach ($settings as [$key, $value]) {  $stmt = $pdo->prepare("  INSERT INTO system_config (config_key, config_value, updated_by, updated_at)  VALUES (?, ?, ?, NOW())  ON DUPLICATE KEY UPDATE  config_value = VALUES(config_value),  updated_by = VALUES(updated_by),  updated_at = NOW()  ");  $stmt->execute([$key, $value, $me['id']]);  }  echo json_encode(['ok' => true, 'message' => 'Alert settings saved successfully']);  break;  default:  echo json_encode(['ok' => false, 'error' => 'Unknown action']);  break;  }  } catch (Exception $e) {  echo json_encode(['ok' => false, 'error' => 'Server error: ' . $e->getMessage()]);
}
